```javascript
const table = document.querySelector('.table');
let sortColumn = null;
let sortOrder = 1; // 1 = ascending, -1 = descending

table.querySelectorAll('th').forEach(th => {
  th.addEventListener('click', () => {
    const sortType = th.dataset.sort;
    const columnIndex = th.cellIndex;

    if (sortColumn === columnIndex) {
      sortOrder *= -1; // Toggle sort order
    } else {
      sortColumn = columnIndex;
      sortOrder = 1;
    }

    sortTable(sortColumn, sortOrder, sortType);
  });
});

function sortTable(column, order, sortType) {
  const rows = Array.from(table.querySelectorAll('tbody tr'));

  rows.sort((a, b) => {
    const cellA = a.cells[column].textContent;
    const cellB = b.cells[column].textContent;

    let comparison = 0;

    switch (sortType) {
      case 'string':
        comparison = cellA.localeCompare(cellB);
        break;
      case 'number':
        comparison = parseFloat(cellA) - parseFloat(cellB);
        break;
      case 'date':
        comparison = new Date(cellA) - new Date(cellB);
        break;
      default:
        comparison = cellA.localeCompare(cellB); // Default to string
    }

    return order * comparison;
  });

  // Re-append the sorted rows to the table body
  const tbody = table.querySelector('tbody');
  tbody.innerHTML = ''; // Clear existing rows
  rows.forEach(row => tbody.appendChild(row));
}
